// One output item per photo, across every email in the batch.
// An email with no usable photo becomes an item with `error` set, which the next IF routes to _failed/.
const SUPPORTED = ['image/jpeg', 'image/png', 'image/gif', 'image/webp'];
const MAX_BASE64 = 5 * 1024 * 1024; // Claude API limit per image
const BY_EXT = { jpg: 'image/jpeg', jpeg: 'image/jpeg', png: 'image/png', gif: 'image/gif', webp: 'image/webp', heic: 'image/heic', heif: 'image/heif' };

// Small content hash so the same photo sent twice is only written once
function fnv1a(buf) {
  let h = 0x811c9dc5;
  for (let i = 0; i < buf.length; i++) { h ^= buf[i]; h = Math.imul(h, 0x01000193); }
  return (h >>> 0).toString(16).padStart(8, '0');
}

const out = [];
const seen = new Set(); // photos already queued in this batch; repeats from earlier runs are caught after Claude
const emails = $input.all();
for (let i = 0; i < emails.length; i++) {
  const email = emails[i].json;
  const meta = {
    subject: email.subject || '',
    from: email.from || '',
    received: email.date || '',
    messageId: (email.metadata || {})['message-id'] || '',
    uid: (email.attributes || {}).uid || '',
  };
  const binary = emails[i].binary || {};
  const keys = Object.keys(binary)
    .filter(k => k.startsWith('attachment_'))
    .sort((a, b) => Number(a.split('_')[1]) - Number(b.split('_')[1]));

  let photoIndex = 0;
  for (const key of keys) {
    const att = binary[key];
    const ext = (att.fileExtension || (att.fileName || '').split('.').pop() || '').toLowerCase();
    let mimeType = (att.mimeType || '').toLowerCase().replace('image/jpg', 'image/jpeg');
    if (!mimeType.startsWith('image/')) mimeType = BY_EXT[ext] || '';
    if (!mimeType) continue; // not a photo (PDF, signature file, ...)

    photoIndex++;
    const buffer = await this.helpers.getBinaryDataBuffer(i, key);
    const hash = `${buffer.length}-${fnv1a(buffer)}`;
    if (seen.has(hash)) continue; // same photo twice in this batch
    seen.add(hash);
    const image_base64 = buffer.toString('base64');
    let error = '';
    if (!SUPPORTED.includes(mimeType)) {
      error = `Unsupported image type ${mimeType}. Claude accepts JPEG, PNG, GIF and WebP (on iPhone: Settings > Camera > Formats > Most Compatible).`;
    } else if (image_base64.length > MAX_BASE64) {
      error = `Photo is too large (${(buffer.length / 1048576).toFixed(1)} MB; the limit is about 3.7 MB). Send it at a smaller size.`;
    }
    out.push({
      json: { ...meta, photoIndex, photoName: att.fileName || `${key}.${ext}`, mimeType, sizeBytes: buffer.length, hash, image_base64, error },
      pairedItem: { item: i },
    });
  }
  if (photoIndex === 0) {
    out.push({
      json: { ...meta, photoIndex: 0, error: 'Email has no photo attachment. Photos pasted inline into the email body are not picked up, so attach the photo as a file.' },
      pairedItem: { item: i },
    });
  }
}
return out;

