// Pull Claude's JSON out of the reply. Any problem becomes `error`, which the next IF routes to _failed/.
const res = $input.item.json;
const { image_base64, ...source } = $('Split photos').item.json;

let note = {};
let error = '';
const text = (res.content || [])
  .filter(block => block.type === 'text')
  .map(block => block.text)
  .join('')
  .replace(/```(json)?/gi, '')
  .trim();

if (res.stop_reason === 'max_tokens') {
  error = 'Reply was cut off (max_tokens reached).';
} else if (res.stop_reason === 'refusal') {
  error = 'Claude declined to transcribe this photo.';
} else {
  try {
    note = JSON.parse(text);
  } catch (e) {
    error = `Reply was not valid JSON: ${e.message}`;
  }
  if (!error && typeof note.body_markdown !== 'string') error = 'Reply is missing body_markdown.';
}

return { json: { ...source, ...note, error, usage: res.usage } };

// One transcribed photo becomes one markdown file in the Raw notes folder.
const RAW_DIR = '/path/to/your/Obsidian Vault/Raw notes';
const TZ = 'Asia/Dhaka';
const n = $input.item.json;

const received = DateTime.fromJSDate(new Date(n.received)).setZone(TZ);
const captured = received.isValid ? received : DateTime.now().setZone(TZ);
const noteDate = /^\d{4}-\d{2}-\d{2}$/.test(n.date || '') ? n.date : captured.toFormat('yyyy-MM-dd');

const title = String(n.title || '').replace(/\s+/g, ' ').trim() || 'Untitled';
const safeTitle = title.replace(/[\\/:]/g, '-').replace(/[*?"<>|#^\[\]]/g, '').replace(/\s+/g, ' ').trim().slice(0, 80) || 'Untitled';
const suffix = n.photoIndex > 1 ? ` (${n.photoIndex})` : '';
const fileName = `${captured.toFormat('yyyy-MM-dd HHmm')} ${safeTitle}${suffix}.md`;

// Obsidian tags: lowercase, no spaces, not purely numeric
const tags = [...new Set((n.tags || [])
  .map(t => String(t).toLowerCase().trim().replace(/^#/, '').replace(/\s+/g, '-').replace(/[^\p{L}\p{N}_\/-]/gu, ''))
  .filter(t => t && !/^\d+$/.test(t)))];

// Drop a leading heading that only repeats the title
const titlePattern = title.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const body = String(n.body_markdown || '')
  .replace(new RegExp('^\\s*#{1,6}\\s*' + titlePattern + '\\s*(\\n|$)', 'i'), '')
  .trim();

const q = value => JSON.stringify(String(value ?? '')); // a JSON string is a valid YAML string
const text = [
  '---',
  `title: ${q(title)}`,
  `date: ${noteDate}`,
  `first_captured: ${captured.toFormat("yyyy-MM-dd'T'HH:mm")}`,
  tags.length ? 'tags:\n' + tags.map(t => `  - ${t}`).join('\n') : 'tags: []',
  'type: raw-note',
  'status: inbox',
  `source: ${q('email: ' + n.subject)}`,
  `photo: ${q(n.photoName)}`,
  '---',
  '',
  `# ${title}`,
  '',
  body,
  '',
].join('\n');

return {
  json: { path: `${RAW_DIR}/${fileName}`, fileName, title },
  binary: {
    data: { data: Buffer.from(text, 'utf8').toString('base64'), mimeType: 'text/markdown', fileName, fileExtension: 'md' },
  },
};

// Anything that couldn't be transcribed lands in _failed/: a note explaining why, plus the original photo.
// Nothing is lost even though the email has already been marked as read.
const FAIL_DIR = '/path/to/your/Obsidian Vault/Raw notes/_failed';
const TZ = 'Asia/Dhaka';

function describe(err) {
  if (!err) return 'Unknown error';
  if (typeof err === 'string') return err;
  return [err.message, err.description].filter(Boolean).join(' | ') || JSON.stringify(err).slice(0, 2000);
}

const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const j = items[i].json;
  const src = $('Split photos').itemMatching(i).json;
  const received = DateTime.fromJSDate(new Date(src.received)).setZone(TZ);
  const when = received.isValid ? received : DateTime.now().setZone(TZ);
  const base = `${when.toFormat('yyyy-MM-dd HHmm')} failed - email ${src.uid || 'unknown'}${src.photoIndex ? '-' + src.photoIndex : ''}`;
  const ext = (src.mimeType || '').split('/')[1] || 'jpg';
  const photoFile = src.image_base64 ? `${base}.${ext === 'jpeg' ? 'jpg' : ext}` : '';

  const text = [
    '---',
    'type: failed-capture',
    'status: needs-retry',
    `first_captured: ${when.toFormat("yyyy-MM-dd'T'HH:mm")}`,
    `source: ${JSON.stringify('email: ' + (src.subject || ''))}`,
    '---',
    '',
    '# Brain Dump capture failed',
    '',
    `**Error:** ${describe(j.error)}`,
    '',
    `**Email:** "${src.subject || ''}" from ${src.from || '?'}, received ${src.received || '?'}`,
    src.photoName ? `**Photo:** ${src.photoName} (${((src.sizeBytes || 0) / 1048576).toFixed(1)} MB)` : '',
    '',
    photoFile ? `![[${photoFile}]]` : '',
    '',
    '**To retry:** send the photo again in a new email with the subject "Brain Dump". Delete this note (and its photo) once it is handled.',
    '',
  ].join('\n');

  out.push({
    json: { path: `${FAIL_DIR}/${base}.md` },
    binary: { data: { data: Buffer.from(text, 'utf8').toString('base64'), mimeType: 'text/markdown', fileName: `${base}.md`, fileExtension: 'md' } },
  });
  if (photoFile) {
    out.push({
      json: { path: `${FAIL_DIR}/${photoFile}` },
      binary: { data: { data: src.image_base64, mimeType: src.mimeType, fileName: photoFile, fileExtension: ext } },
    });
  }
}
return out;
